#!/usr/bin/env python3
"""Summarize successes and intentional failures without hiding failed fixtures."""
from pathlib import Path
import argparse,collections,datetime,hashlib,json
ap=argparse.ArgumentParser();ap.add_argument('--out',type=Path,required=True);ap.add_argument('--inputs',type=Path,nargs='+',required=True);args=ap.parse_args();ROOT=Path(__file__).resolve().parents[1];OUT=args.out.resolve();OUT.mkdir(exist_ok=True)
rows=[];runs=[];sources=[]
for directory in args.inputs:
    p=directory.resolve();records=json.loads((p/'results.json').read_text());verification=json.loads((p/'independent-verification.json').read_text());bykey={(r['label'],r['iteration']):r for r in verification['records']}
    manifest=json.loads((p/'manifest.json').read_text());assert manifest['system_unchanged'] and not manifest['halted_live_process'];sources.append({'directory':str(p),'manifest':manifest,'verification':{k:v for k,v in verification.items() if k!='records'}})
    for record in records:
        d=record.get('result',{});raw=[bykey[(record['label'],r['iteration'])] for r in d.get('runs',[])];passed=bool(d.get('passed')) and all(r['mismatches']==0 and r['guard_mismatches']==0 for r in raw) and len(raw)==3
        rows.append({'suite':p.name,'label':record['label'],'kind':record['kind'],'op':record.get('op'),'implementation':record.get('implementation','native'),'runtime_language':record.get('runtime_language'),'address_space':record.get('address_space'),'contended':record.get('contended'),'variant':record.get('variant'),'storage':record.get('storage'),'local':record['local'],'groups':record['groups'],'resources':record.get('resources'),'passed':passed,'failure_stage':d.get('failure_stage',record.get('failure_stage')),'error':d.get('error',record.get('stderr','')),'raw_runs':len(raw),'words_checked':sum(r['words_checked'] for r in raw),'independent_mismatches':sum(r['mismatches'] for r in raw),'guard_mismatches':sum(r['guard_mismatches'] for r in raw),'source_sha256':record['source_sha256'],'record_directory':str(p),'execution_directory':record.get('execution_dir')})
        runs.extend(raw)
hist=collections.Counter((r['kind'],r['implementation'],r['address_space'],r['passed']) for r in rows)
counts=[{'kind':k[0],'implementation':k[1],'address_space':k[2],'passed':k[3],'cases':v} for k,v in hist.items()]
summary={'collected_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'cases':len(rows),'cases_passed':sum(r['passed'] for r in rows),'cases_failed':sum(not r['passed'] for r in rows),'raw_runs_checked':len(runs),'words_checked':sum(r['words_checked'] for r in runs),'numeric_mismatches_in_preserved_failures':sum(r['mismatches'] for r in runs),'guard_mismatches':sum(r['guard_mismatches'] for r in runs),'performance_benchmark':False,'counts':counts,'sources':sources,'cases_detail':rows,'scope':'Native public Metal calls and application-local shuffle helpers; no NAK import, driver modification or full API-family qualification. Known CAS and compiler failures retained.'}
(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps({k:v for k,v in summary.items() if k not in ['sources','cases_detail']},indent=2))
lines=['FONCTIONS METAL NATIVES / GTX 880M — 13 octobre 2026','',f"{len(rows)} configurations; {summary['cases_passed']} passent; {summary['cases_failed']} échecs conservés.",f"{len(runs)} captures brutes vérifiées au CPU, {summary['words_checked']} mots uint32.",'Les échecs numériques CAS sont conservés et comptés; un command buffer Completed ne les transforme pas en succès.','Aucun benchmark de performance dans cette série.','','ARGUMENT BUFFERS TIER 2','Encodage CPU: tableaux de buffers, textures R32Float et samplers, indices variables.','Encodage GPU: permutation de références vers un second argument buffer Private puis consommation dans un autre encodeur.','Buffers référencés Private avec offsets 64B, pool conservé et useResource; rebinding entre trois exécutions.','Les sorties sont relues après synchronisation et vérifiées indépendamment.','Cela qualifie ces opérations et tailles, pas toute la conformité tier 2.','','SIMD','Intrinsics natifs et compilation runtime/offline sont distingués dans summary.json.','KeplerSIMD.metalh utilise simd_shuffle, déjà exécuté, pour des réductions sur warps de 32 lanes.','Tests couvrent groupes 1/31/32/33/63/128; cas odd-mask explicitement reconvergé.','Somme FP32 testée sur valeurs dyadiques; pas de qualification NaN/Inf/denorm/arrondi général.','Le helper exige appel convergent de toutes les lanes actives; il ne remplace pas des appels divergents arbitraires.','Les opérations exécutées par les helpers ne rendent pas les intrinsics natifs disponibles aux applications existantes.','','CAS','Device/global et threadgroup/shared sont des cas distincts, avec succès/échec de comparaison et contention.','Le compteur final, le booléen et la valeur expected sont vérifiés séparément; les retours ADD sont validés comme multiset.','Les captures montrent les éventuelles valeurs expected incorrectes sans les masquer par un atomic_load après échec.','La boucle de retry est bornée à 128; aucune qualification de progrès général ou forte contention prolongée.','L’ancien échec Invalid Resource du fixture shared précédent reste une anomalie distincte.','','CONFIGURATION ET LIMITES','macOS 26.7.1 / 25G241; GTX 880M dédiée, registry ID enregistré dans chaque exécution.','GeForceMTLDriver SHA256 2b89839c425d95934f5e01f16c8683fe53432df410292ec8e554b21c98d6c054.','Shader compilation xcrun Metal -std=macos-metal2.4 -fno-fast-math, ou newLibraryWithSource avec version MSL enregistrée.','Sources, shaders, commandes, versions et manifests de processus conservés dans les suites.','Processus propres signés ad hoc; aucun import NAK ni KPCreatePipeline lié à la sonde.','Le résultat reste applicatif/compilateur: aucun nouveau pilote installé, aucune famille Metal annoncée.','','REPRODUCTION — depuis bridge']
for p in args.inputs:
    m=json.loads((p/'manifest.json').read_text());only=m.get('only','arguments' if 'arguments' in p.name else 'cas' if 'cas' in p.name else 'simd');lines.append(f"python3 tools/reproduce_native_features.py --out results/{p.name}-reproduction --selection extended --only {only}");lines.append(f"python3 tools/verify_native_features.py --input results/{p.name}-reproduction")
lines.extend(['Le vérificateur retourne 1 sur les cas CAS volontairement conservés comme échecs: lire les détails, pas seulement le code de sortie.','Utiliser toujours un dossier inédit. Ne pas relancer un child indiqué encore vivant dans manifest.json.','','DÉTAIL DES CAS'])
for r in rows:lines.append(f"{r['suite']}/{r['label']} [{r['implementation']}] {'PASS' if r['passed'] else 'FAIL '+str(r['failure_stage'])}; {r['raw_runs']} captures; {r['independent_mismatches']} écarts; {r['guard_mismatches']} gardes.")
(OUT/'RAPPORT.txt').write_text('\n'.join(lines)+'\n')
